func writeNoteText(t *testing.T, path, text string) string {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(text), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

// suiteNote ports the suite's _note helper byte-for-byte (the empty
// extra_fm line included).
func suiteNote(t *testing.T, dir, name, url string, tags []string, body, extraFM string) string {
	t.Helper()
	tagLine := "tags: [" + strings.Join(tags, ", ") + "]"
	text := "---\nsource: \"" + url + "\"\n" + tagLine +
		"\ncategory: \"\"\nsubcategory: \"\"\nmanaged_by: \"gitcurator\"\n" +
		extraFM + "\n---\n\n# A Note\n\n" + body + "\n"
	return writeNoteText(t, filepath.Join(dir, name), text)
}

func suiteVault(t *testing.T) (vault, db string) {
	t.Helper()
	tmp := t.TempDir()
	vault = filepath.Join(tmp, "websites")
	if err := os.MkdirAll(vault, 0o755); err != nil {
		t.Fatal(err)
	}
	return vault, filepath.Join(tmp, "reads.db")
}

// noteReadsBanished is a TEST-LOCAL port of website_pipeline's
// _note_reads_banished (the banishment walk's frontmatter predicate),
// used only to replicate the consumer's ask pattern in the walk tests
// below. The real predicate ports with internal/websitepipeline
// (T-23+); until then the golden's banish_marks/deletions — generated
// through the reference's own predicate — pin its behavior.
func noteReadsBanished(fm *Banish) (bool, string) {
	if fm == nil {
		return false, ""
	}
	for _, tag := range fm.Tags {
		s := helpers.PyLower(helpers.Strip(tag))
		s = helpers.Strip(strings.TrimLeft(s, "#"))
		if s == "" {
			continue
		}
		if strings.Contains(s, BanishEmoji) {
			return true, helpers.Strip(tag)
		}
		for _, w := range BanishWords {
			if s == w {
				return true, helpers.Strip(tag)
			}
		}
	}
	for _, kv := range fm.Banish {
		if !banishKeySet[kv.Key] {
			continue // a stranger's key is never our verdict
		}
		switch helpers.PyLower(helpers.Strip(kv.Value)) {
		case "true", "yes", "1", "on":
			return true, kv.Key + ": " + kv.Value
		}
	}
	return false, ""
}

// banishWalk replicates the banishment door's ask pattern
// (website_pipeline's walk): frontmatter first, the body tag only when
// the frontmatter door did not mark the note.
func banishWalk(t *testing.T, c *Cache, vault string) []string {
	t.Helper()
	entries, err := os.ReadDir(vault)
	if err != nil {
		t.Fatal(err)
	}
	var markers []string
	for _, e := range entries {
		if !strings.HasSuffix(strings.ToLower(e.Name()), ".md") {
			continue
		}
		p := filepath.Join(vault, e.Name())
		fm := c.BanishFrontmatter(p)
		if fm == nil {
			continue // not a frontmattered note — a human's
		}
		marked, marker := noteReadsBanished(fm)
		if !marked {
			marker = c.BanishTag(p)
			marked = marker != ""
		}
		if marked {
			markers = append(markers, marker)
		}
	}
	return markers
}

// inventoryWalk replicates the inventory door's ask pattern
// (vault_scan's walk): frontmatter per note.
func inventoryWalk(t *testing.T, c *Cache, vault string) {
	t.Helper()
	entries, err := os.ReadDir(vault)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if !strings.HasSuffix(strings.ToLower(e.Name()), ".md") {
			continue
		}
		c.Frontmatter(filepath.Join(vault, e.Name()))
	}
}

func statsToG(s Stats) statsG {
	return statsG{Opens: s.Opens, RamHits: s.RamHits, DbHits: s.DbHits,
		DbWrites: s.DbWrites, NotesParsed: s.NotesParsed}
}

func assertStats(t *testing.T, ctx string, got Stats, want statsG) {
	t.Helper()
	if g := statsToG(got); g != want {
		t.Errorf("%s stats = %+v; reference golden recorded %+v", ctx, g, want)
	}
}

// ---------------------------------------------------------------------------
// THE UNIFIED PARSE (ported TestTheUnifiedParse).
// ---------------------------------------------------------------------------

func TestTheUnionOfBothDoorsKeys(t *testing.T) {
	fm := ParseFrontmatterUnified(
		"---\nsource: \"https://a.example/x\"\n" +
			"category: \"Design\"\nsubcategory: \"Assets\"\n" +
			"managed_by: \"gitcurator\"\nkind: \"directory\"\n" +
			"fetch_status: \"full\"\ntags: [icons, mockup]\n" +
			"blacklist: true\n---\n\n# t\n")
	if !fm.HasFM {
		t.Fatal("has_fm = false; want true")
	}
	if fm.Source != "https://a.example/x" || fm.Category != "Design" ||
		fm.Subcategory != "Assets" || fm.ManagedBy != "gitcurator" ||
		fm.Kind != "directory" || fm.FetchStatus != "full" {
		t.Errorf("string keys mismatch: %+v", fm)
	}
	if !reflect.DeepEqual(fm.Tags, []string{"icons", "mockup"}) {
		t.Errorf("tags = %v; want [icons mockup]", fm.Tags)
	}
	if len(fm.Banish) != 1 || fm.Banish[0] != (KV{"blacklist", "true"}) {
		t.Errorf("banish = %v; want [{blacklist true}]", fm.Banish)
	}
}

func TestTheBlockStyleTagListReads(t *testing.T) {
	fm := ParseFrontmatterUnified(
		"---\nsource: \"https://a.example/x\"\ntags:\n" +
			"  - \"auto_delete\"\n  - web\n---\n\n# t\n")
	if !reflect.DeepEqual(fm.Tags, []string{"auto_delete", "web"}) {
		t.Errorf("tags = %v; want [auto_delete web]", fm.Tags)
	}
}

func TestANoteWithoutFrontmatterIsTheEmptyShape(t *testing.T) {
	fm := ParseFrontmatterUnified("# just a heading\n\nbody")
	if fm.HasFM {
		t.Error("has_fm = true; want false")
	}
	if fm.Source != "" || len(fm.Tags) != 0 || len(fm.Banish) != 0 {
		t.Errorf("empty shape violated: %+v", fm)
	}
}

func TestAnUnterminatedBlockStillParsesItsKeys(t *testing.T) {
	// the doors' own law: an unterminated block is all frontmatter
	fm := ParseFrontmatterUnified("---\nsource: \"https://a.example/x\"\n")
	if !fm.HasFM || fm.Source != "https://a.example/x" {
		t.Errorf("unterminated block: %+v", fm)
	}
}

// ---------------------------------------------------------------------------
// THE BODY TAG — parity with the banishment door's own scan (the
// golden's body corpus; the reference's suite proved
// body_banish_tag_of == wp._note_body_banish_tag on the frontmattered
// corpus, so these reference answers ARE the direct door's).
// ---------------------------------------------------------------------------

func TestTheBodyTagByteIdenticalWithTheDirectDoor(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "notereads_pure.golden.json", &g)
	for _, tc := range g.BodyTagCases {
		if got := BodyBanishTagOf(tc.Text); got != tc.Tag {
			t.Errorf("body %s/%d %q: tag = %q; reference (the direct door's own answer) = %q",
				tc.Group, tc.Index, tc.Text, got, tc.Tag)
		}
	}
	// The no-frontmatter law the corpus pins: a text whose first line is
	// not '---' has NO scannable body (start = len(lines) — the shared
	// quirk of both doors, preserved).
	if got := BodyBanishTagOf("not needed #auto-delete"); got != "" {
		t.Errorf("no-frontmatter body: tag = %q; want '' (the start=len(lines) law)", got)
	}
}

// ---------------------------------------------------------------------------
// THE RAM TEXT LAYER — the one-open law within a scan (ported
// TestTheRamLayer).
// ---------------------------------------------------------------------------

func TestOneOpenPerNotePerScan(t *testing.T) {
	vault, _ := suiteVault(t)
	p := suiteNote(t, vault, "a.md", "https://a.example/a", nil, "", "")
	c := New("")
	defer c.Close(false)
	first := c.Text(p, DefaultTextBytes)
	second := c.Text(p, DefaultTextBytes) // the banishment body ask
	third := c.Text(p, 16_000)            // the inventory head ask
	if first != second {
		t.Fatal("second ask diverged")
	}
	if !strings.HasPrefix(first, "---") {
		t.Fatalf("text does not start with frontmatter: %q", first[:20])
	}
	if third != helpers.CutRunes(first, 16_000) {
		t.Error("third ask is not the first 16,000 chars of the first")
	}
	stats := c.Stats()
	if stats.Opens != 1 { // ONE open, three asks
		t.Errorf("opens = %d; want 1 (one open per note per scan)", stats.Opens)
	}
	if stats.RamHits < 2 {
		t.Errorf("ram_hits = %d; want >= 2", stats.RamHits)
	}
}

func TestABiggerAskReReadsOnce(t *testing.T) {
	vault, _ := suiteVault(t)
	p := suiteNote(t, vault, "a.md", "https://a.example/a", nil, "", "")
	c := New("")
	defer c.Close(false)
	small := c.Text(p, 10)
	big := c.Text(p, 200_000)
	if n := len([]rune(small)); n != 10 {
		t.Errorf("small ask = %d chars; want 10", n)
	}
	if !strings.HasPrefix(big, "---") {
		t.Error("big ask does not start with frontmatter")
	}
	if c.Stats().Opens != 2 {
		t.Errorf("opens = %d; want 2 (a bigger ask re-reads once)", c.Stats().Opens)
	}
	// and the bigger text now serves the smaller ask for free
	again := c.Text(p, 10)
	if again != helpers.CutRunes(big, 10) {
		t.Error("small re-ask is not a slice of the bigger text")
	}
	if c.Stats().Opens != 2 {
		t.Errorf("opens = %d after the free re-ask; want 2", c.Stats().Opens)
	}
}

func TestAChangedNoteReReads(t *testing.T) {
	vault, _ := suiteVault(t)
	p := suiteNote(t, vault, "a.md", "https://a.example/a", nil, "", "")
	c := New("")
	defer c.Close(false)
	before := c.Frontmatter(p)
	if before.Source != "https://a.example/a" {
		t.Fatalf("before source = %q", before.Source)
	}
	suiteNote(t, vault, "a.md", "https://b.example/changed", nil, "", "") // a mid-scan edit
	after := c.Frontmatter(p)
	if after.Source != "https://b.example/changed" {
		t.Errorf("after source = %q; want the changed one (stat fingerprint)", after.Source)
	}
	if c.Stats().Opens < 2 {
		t.Errorf("opens = %d; want >= 2 (a changed note re-reads honestly)", c.Stats().Opens)
	}
}

