// ---------------------------------------------------------------------------
// THE PERSISTED LAYER — the next scan opens nothing (ported
// TestThePersistedLayer; the walk asks replicate the reference's own
// build_scan_plan pattern, counts pinned by the behavior golden).
// ---------------------------------------------------------------------------

func TestTheSecondScanOfUnchangedNotesOpensNothing(t *testing.T) {
	var bg behaviorGolden
	decodeGolden(t, "notereads_behavior.golden.json", &bg)
	probe := bg.Probes.SecondScan

	vault, db := suiteVault(t)
	suiteNote(t, vault, "one.md", "https://a.example/1", nil, "", "")
	suiteNote(t, vault, "two.md", "https://a.example/2", nil, "not needed #auto-delete", "")
	suiteNote(t, vault, "three.md", "https://a.example/3", []string{"auto_delete"}, "", "")
	writeNoteText(t, filepath.Join(vault, "hand.md"), "# my own note, no frontmatter")

	c1 := New(db)
	markers1 := banishWalk(t, c1, vault)
	inventoryWalk(t, c1, vault)
	assertStats(t, "pass1", c1.Stats(), probe.Pass1Stats)
	c1.Close(true)

	c2 := New(db)
	markers2 := banishWalk(t, c2, vault)
	inventoryWalk(t, c2, vault)
	stats2 := c2.Stats()
	assertStats(t, "pass2", c2.Stats(), probe.Pass2Stats)
	c2.Close(true)

	if stats2.Opens != 0 { // the near-instant law
		t.Errorf("pass2 opens = %d; want 0 (the next scan opens nothing)", stats2.Opens)
	}
	if stats2.DbHits <= 0 {
		t.Errorf("pass2 db_hits = %d; want > 0", stats2.DbHits)
	}
	// the story is IDENTICAL — the memory changed no answer
	if !reflect.DeepEqual(markers1, markers2) {
		t.Errorf("markers pass1 %v != pass2 %v", markers1, markers2)
	}
	// walk order (alphabetical): three.md's frontmatter mark before
	// two.md's body mark — in BOTH scans (the golden's deletions).
	var want []string
	for _, d := range probe.Deletions2 {
		want = append(want, d.Marker)
	}
	if !reflect.DeepEqual(markers2, want) {
		t.Errorf("pass2 markers = %v; reference deletions recorded %v", markers2, want)
	}
}

