// ---------------------------------------------------------------------------
// THE PURE GOLDEN — the parsers, the fold, the text-mode read law, the
// version gate, the grammar mirrors, the constants.
// ---------------------------------------------------------------------------

func TestPureGolden(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "notereads_pure.golden.json", &g)

	if ParseVersion != g.ParseVersion {
		t.Errorf("ParseVersion = %d; reference %d", ParseVersion, g.ParseVersion)
	}
	if DefaultTextBytes != g.DefaultTextBytes || DefaultRAMBudget != g.DefaultRAMBudget {
		t.Errorf("constants: text=%d/ram=%d; reference text=%d/ram=%d",
			DefaultTextBytes, DefaultRAMBudget, g.DefaultTextBytes, g.DefaultRAMBudget)
	}
	if BanishEmoji != g.BanishGrammarMirror.Emoji {
		t.Errorf("BanishEmoji = %q; reference %q", BanishEmoji, g.BanishGrammarMirror.Emoji)
	}
	if !sameStrings(BanishWords, g.BanishGrammarMirror.Words) {
		t.Errorf("BanishWords = %v; reference %v", BanishWords, g.BanishGrammarMirror.Words)
	}
	if !sameStrings(BanishKeys, g.BanishGrammarMirror.Keys) {
		t.Errorf("BanishKeys = %v; reference %v", BanishKeys, g.BanishGrammarMirror.Keys)
	}
	if bodyTagStops != g.BanishGrammarMirror.Stops {
		t.Errorf("bodyTagStops = %q; reference %q", bodyTagStops, g.BanishGrammarMirror.Stops)
	}

	// the parse corpus
	for _, tc := range g.ParseCases {
		got := ParseFrontmatterUnified(tc.Text)
		if err := compareUnified(t, tc.Name, got, tc.FM, false); err != nil {
			t.Error(err)
		}
	}

	// the truthy battery (the lock doors' own tolerance)
	for _, tc := range g.TruthyCases {
		in, _ := tc[0].(string)
		want, _ := tc[1].(bool)
		if got := truthy(in); got != want {
			t.Errorf("truthy(%q) = %v; reference %v", in, got, want)
		}
	}

	// the text-mode read law: byte payloads → n — universal newlines,
	// maximal-subpart replacement, the rune cut, the BOM passthrough.
	for _, tc := range g.ReadBoundedCases {
		data := make([]byte, len(tc.Bytes))
		for i, b := range tc.Bytes {
			data[i] = byte(b)
		}
		p := writeNoteText(t, filepath.Join(t.TempDir(), tc.Name+".md"), string(data))
		if got := readBounded(p, tc.N); got != tc.Out {
			t.Errorf("read_bounded(%s, %d) = %q; reference %q",
				tc.Name, tc.N, got, tc.Out)
		}
	}

	// the version gate battery (rows as raw JSON, exactly what the DB
	// hands the reader)
	for _, tc := range g.RowIsCurrentCases {
		raw, err := json.Marshal(tc[0])
		if err != nil {
			t.Fatal(err)
		}
		want, _ := tc[1].(bool)
		if got := rowIsCurrent(raw); got != want {
			t.Errorf("row_is_current(%s) = %v; reference %v", raw, got, want)
		}
	}
}

// TestUnifiedFromJSONGolden — the reference's own row reader, including
// THE STARS QUIRK'S EVIDENCE: the reference's output drops `stars`
// (golden `out.stars` == ” while the row carries it). The Go port
// applies the documented pre-classified fix and restores it — asserted
// on exactly that key in TestDBHitRowsCarryStars; every other key must
// match the reference byte-for-byte.
func TestUnifiedFromJSONGolden(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "notereads_pure.golden.json", &g)
	for _, tc := range g.UnifiedFromJSONCases {
		got, ok := unifiedFromJSON(tc.Row)
		if !ok {
			t.Fatalf("%s: unifiedFromJSON failed on %s", tc.Name, tc.Row)
		}
		if err := compareUnified(t, tc.Name, got, tc.Out, true); err != nil {
			t.Error(err)
		}
		// the stars key is the documented divergence: the
		// reference drops it (the golden's own out is the
		// quirk's evidence), the port restores the row's value
		var rowStars struct {
			Stars string `json:"stars"`
		}
		if len(tc.Row) > 0 {
			if err := json.Unmarshal(tc.Row, &rowStars); err != nil {
				t.Fatalf("%s: row decode: %v", tc.Name, err)
			}
		}
		if got.Stars != rowStars.Stars {
			t.Errorf("%s: stars = %q; the fix restores the row's own %q",
				tc.Name, got.Stars, rowStars.Stars)
		}
		if got, want := rowIsCurrent(tc.Row), tc.RowIsCurrent; got != want {
			t.Errorf("%s: row_is_current = %v; reference %v", tc.Name, got, want)
		}
	}
}

// TestDBHitRowsCarryStars — THE DOCUMENTED PRE-CLASSIFIED FIX (spec
// quirk 1): the reference's _unified_from_json iterates only
// _FM_STRING_KEYS, so a DB-hit row's `stars` reads ” (the golden's
// full_row_with_stars case records stars-in "1200" → stars-out ""). The
// Go port restores the row's own value.
func TestDBHitRowsCarryStars(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "notereads_pure.golden.json", &g)
	var fullRow *struct {
		Stars string `json:"stars"`
	}
	for _, tc := range g.UnifiedFromJSONCases {
		if tc.Name != "full_row_with_stars" {
			continue
		}
		if err := json.Unmarshal(tc.Row, &fullRow); err != nil {
			t.Fatal(err)
		}
		got, ok := unifiedFromJSON(tc.Row)
		if !ok {
			t.Fatal("unifiedFromJSON failed")
		}
		if got.Stars != fullRow.Stars {
			t.Errorf("stars on DB hit = %q; want the row's own %q (the documented fix)",
				got.Stars, fullRow.Stars)
		}
		// the reference's quirk evidence, on the record
		if tc.Out.Stars != "" {
			t.Errorf("golden reference stars-out = %q; the quirk evidence expected ''",
				tc.Out.Stars)
		}
	}

	// the full path through the cache: a repos note's stars survive a
	// close+reopen (the next scan reads them from the remembered row).
	vault, db := suiteVault(t)
	p := writeNoteText(t, filepath.Join(vault, "repos.md"),
		"---\nsource: \"https://github.com/o/r\"\nprimary_language: \"Go\"\n"+
			"org: \"golang\"\nstars: \"1200\"\nkind: \"repository\"\n---\nbody\n")
	c1 := New(db)
	if got := c1.Frontmatter(p).Stars; got != "1200" {
		c1.Close(true)
		t.Fatalf("first scan stars = %q; want 1200", got)
	}
	c1.Close(true)
	c2 := New(db)
	defer c2.Close(true)
	fm := c2.Frontmatter(p)
	if c2.Stats().Opens != 0 {
		t.Errorf("second scan opens = %d; want 0 (served from the row)", c2.Stats().Opens)
	}
	if fm.Stars != "1200" {
		t.Errorf("DB-hit stars = %q; want 1200 (the documented fix — the reference drops it)",
			fm.Stars)
	}
}

// TestParseVersionGate — stale rows re-parse ONCE (frontmatter), while
// banish_tag is NOT version-gated (served from the stale row — the
// spec's quirk 3, preserved). The golden's stale_rows probe recorded
// the reference's own counts.
func TestParseVersionGate(t *testing.T) {
	var bg behaviorGolden
	decodeGolden(t, "notereads_behavior.golden.json", &bg)
	probe := bg.Probes.StaleRows

	vault, db := suiteVault(t)
	alpha := suiteNote(t, vault, "alpha.md", "https://a.example/a", nil, "", "")
	beta := suiteNote(t, vault, "beta.md", "https://a.example/b", nil, "see #banish now", "")
	c1 := New(db)
	c1.Frontmatter(alpha)
	c1.Frontmatter(beta)
	c1.Close(true)

	// corpus construction (the generator's own probe shape): rewrite
	// alpha's row to v:3 and strip beta's version marker.
	mutateRow(t, db, alpha, func(m map[string]any) { m["v"] = 3 })
	mutateRow(t, db, beta, func(m map[string]any) { delete(m, "v") })

	c2 := New(db)
	fmAlpha := c2.Frontmatter(alpha) // v:3 → re-parse once
	tagBeta := c2.BanishTag(beta)    // NOT gated → served from the row
	fmBeta := c2.Frontmatter(beta)   // no v → re-parse once
	if fmAlpha.Source != probe.FmAlphaSource {
		t.Errorf("alpha source = %q; reference %q", fmAlpha.Source, probe.FmAlphaSource)
	}
	if tagBeta != probe.TagBeta {
		t.Errorf("beta tag = %q; reference %q (the not-version-gated law)", tagBeta, probe.TagBeta)
	}
	if fmBeta.Source != probe.FmBetaSource {
		t.Errorf("beta source = %q; reference %q", fmBeta.Source, probe.FmBetaSource)
	}
	assertStats(t, "stale-rows", c2.Stats(), probe.Stats)
	c2.Close(true)

	// both rows re-remembered with the current grammar
	for name, want := range probe.RestoredVersions {
		if got := readRowVersion(t, db, filepath.Join(vault, name)); got != want {
			t.Errorf("%s restored v = %d; reference %d", name, got, want)
		}
	}
}

// TestFIFOEvictionIsByteBudgeted — the documented pre-classified fix
// (spec quirk 2): the reference counts the RAM budget in CHARACTERS
// (the golden's ram_budget_chars probe: a 150,000-char text of é —
// 300,000 bytes — stays cached under the DEFAULT_TEXT_BYTES floor
// budget, reference opens 1 / ram_hits 1); the Go port counts BYTES,
// so the same text evicts itself and the second ask re-opens — the
// divergence is deliberate, internal-only, and pinned here.
func TestFIFOEvictionIsByteBudgeted(t *testing.T) {
	var bg behaviorGolden
	decodeGolden(t, "notereads_behavior.golden.json", &bg)
	probe := bg.Probes.RamBudgetChars
	if probe.Budget != DefaultTextBytes || probe.Stats.Opens != 1 || probe.Stats.RamHits != 1 {
		t.Fatalf("golden baseline changed: %+v (the reference's CHAR accounting at the floor budget)",
			probe.Stats)
	}

	vault, _ := suiteVault(t)
	p := writeNoteText(t, filepath.Join(vault, "wide.md"), strings.Repeat("é", 150_000))
	c := New("", DefaultTextBytes) // the constructor's floor budget
	defer c.Close(false)
	t1 := c.Text(p, 150_000)
	if n := len([]rune(t1)); n != probe.TextChars {
		t.Fatalf("text = %d chars; reference %d", n, probe.TextChars)
	}
	t2 := c.Text(p, 5)
	if t2 != probe.SecondAsk {
		t.Errorf("second ask = %q; reference %q", t2, probe.SecondAsk)
	}
	if got := c.Stats().Opens; got != 2 {
		t.Errorf("opens = %d; want 2 — the BYTE-budget fix (300,000 bytes > %d; the reference's char accounting kept it at 1)",
			got, DefaultTextBytes)
	}

	// FIFO order itself (ASCII, where chars == bytes — parity with
	// the reference's eviction law): A evicted before B when C
	// arrives. The floor is DEFAULT_TEXT_BYTES, so the texts must
	// exceed it: 100,000-char notes under a 200,001 budget.
	const n = 100_000
	pa := writeNoteText(t, filepath.Join(vault, "a.md"), strings.Repeat("a", n))
	pb := writeNoteText(t, filepath.Join(vault, "b.md"), strings.Repeat("b", n))
	pc := writeNoteText(t, filepath.Join(vault, "c.md"), strings.Repeat("c", n))
	// budget 5n/2+1: a+b (2n) fits; c (3n) evicts A (FIFO) back to
	// 2n; A's 10-char re-read (2n+10) fits WITHOUT evicting B —
	// with the tighter 2n+1 budget the re-read itself overflows and
	// evicts B (Python's own arithmetic, verified while porting).
	c2 := New("", 5*n/2+1)
	defer c2.Close(false)
	c2.Text(pa, n)
	c2.Text(pb, n)
	c2.Text(pc, n)  // 3n > 5n/2+1 → evicts A (FIFO)
	c2.Text(pa, 10) // re-read (A was evicted)
	c2.Text(pb, 10) // RAM hit
	got := c2.Stats()
	if got.Opens != 4 {
		t.Errorf("opens = %d; want 4 (A,B,C then A again after FIFO eviction)", got.Opens)
	}
	if got.RamHits != 1 {
		t.Errorf("ram_hits = %d; want 1 (B served from the RAM layer)", got.RamHits)
	}
}

