// ---------------------------------------------------------------------------
// THE SCHEMA IDENTITY — adopt-as-is DDL (ADR-0003) + the CAST-law guard
// (every column TEXT/INTEGER/REAL-declared; a TIMESTAMP declaration
// would change the DDL bytes and fail here, forcing the CAST).
// ---------------------------------------------------------------------------

func TestSchemaIdentity(t *testing.T) {
	var sg schemaGolden
	decodeGolden(t, "notereads_schema.golden.json", &sg)

	_, db := suiteVault(t)
	c := New(db)
	defer c.Close(true)

	var tableSQL *string
	for _, obj := range sg.ObjectsRaw {
		if obj == nil || len(obj) != 4 {
			continue
		}
		if obj[0] != nil && *obj[0] == "table" && obj[1] != nil && *obj[1] == "note_reads" {
			tableSQL = obj[3]
		}
	}
	if tableSQL == nil {
		t.Fatal("golden carries no note_reads table DDL")
	}
	var gotSQL string
	if err := c.db.SQL().QueryRow(
		"SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'note_reads'",
	).Scan(&gotSQL); err != nil {
		t.Fatal(err)
	}
	if gotSQL != *tableSQL {
		t.Errorf("stored DDL diverges (sqlite_master keeps the NORMALIZED form — IF NOT EXISTS dropped):\n got: %q\nwant: %q",
			gotSQL, *tableSQL)
	}

	// PRAGMA table_info: name, type, notnull, dflt, pk — in order.
	rows, err := c.db.SQL().Query("PRAGMA table_info(note_reads)")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var got [][]any
	for rows.Next() {
		var cid int
		var name, typ string
		var notnull int
		var dflt sql.NullString
		var pk int
		if err := rows.Scan(&cid, &name, &typ, &notnull, &dflt, &pk); err != nil {
			t.Fatal(err)
		}
		var d any
		if dflt.Valid {
			d = dflt.String
		}
		got = append(got, []any{name, typ, notnull, d, pk})
	}
	if len(got) != len(sg.TableColumns) {
		t.Fatalf("table_info rows = %d; golden %d", len(got), len(sg.TableColumns))
	}
	for i, want := range sg.TableColumns {
		wName, _ := want[0].(string)
		wType, _ := want[1].(string)
		wNotnull, _ := want[2].(float64)
		wPk, _ := want[4].(float64)
		gName, _ := got[i][0].(string)
		gType, _ := got[i][1].(string)
		gNotnull, _ := got[i][2].(int)
		gPk, _ := got[i][4].(int)
		if gName != wName || gType != wType || gNotnull != int(wNotnull) || gPk != int(wPk) {
			t.Errorf("column %d = (%s %s nn=%d pk=%d); golden (%s %s nn=%d pk=%d)",
				i, gName, gType, gNotnull, gPk, wName, wType, int(wNotnull), int(wPk))
		}
		// the CAST-law guard: only TEXT/INTEGER/REAL declarations
		switch gType {
		case "TEXT", "INTEGER", "REAL":
		default:
			t.Errorf("column %s declared %q — a timestamp declaration needs the CAST read law (ADR-0003 Am.1)",
				gName, gType)
		}
	}
}

// ---------------------------------------------------------------------------
// THE PYTHON-CREATED FIXTURE — the T-22 acceptance: the reference's own
// cache built this note_reads table; the port opens it with every row
// byte-exact, the atomic pair tied, the pragmas as the reference's own
// open set them (plus the documented unified-pragmas divergence), and
// the rows served through the ported accessor.
// ---------------------------------------------------------------------------

func TestOpenPythonCreatedFixture(t *testing.T) {
	var fg fixtureGolden
	decodeGolden(t, "notereads_fixture_content.golden.json", &fg)
	src := filepath.Join("testdata", "notereads_python_created.db")

	// The atomic-pair tie: the committed fixture is exactly the file the
	// content golden describes.
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if got := sha256Hex(data); got != fg.FixtureSha256 {
		t.Fatalf("fixture sha256 = %s; golden records %s "+
			"(regenerate BOTH with testdiff/goldens/dump_notereads.py)",
			got, fg.FixtureSha256)
	}
	if !fg.NoSidecars {
		t.Fatal("golden records sidecars after close — broken fixture")
	}

	// Never mutate testdata: work on a copy.
	work := filepath.Join(t.TempDir(), "notereads_python_created.db")
	if err := os.WriteFile(work, data, 0o644); err != nil {
		t.Fatal(err)
	}

	c := New(work)
	defer c.Close(true)

	// The pragmas: the Go open sets busy_timeout=30000 like the
	// reference's own open, and — the DOCUMENTED unified-pragmas
	// divergence (store/doc.go) — flips a lone NoteReadCache file from
	// the reference's 'delete'/FULL to wal/NORMAL.
	var mode string
	var busy, sync int64
	if err := c.db.SQL().QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatal(err)
	}
	if err := c.db.SQL().QueryRow("PRAGMA busy_timeout").Scan(&busy); err != nil {
		t.Fatal(err)
	}
	if err := c.db.SQL().QueryRow("PRAGMA synchronous").Scan(&sync); err != nil {
		t.Fatal(err)
	}
	if busy != fg.PragmasThroughRef.BusyTimeout {
		t.Errorf("busy_timeout = %d; the reference's own open sets %d", busy, fg.PragmasThroughRef.BusyTimeout)
	}
	if fg.PragmasThroughRef.JournalMode != "delete" {
		t.Errorf("golden reference journal_mode = %q; the generator expected 'delete'",
			fg.PragmasThroughRef.JournalMode)
	}
	if mode != "wal" {
		t.Errorf("journal_mode after Go open = %q; want 'wal' (the documented unified-pragmas divergence)", mode)
	}
	if sync != 1 {
		t.Errorf("synchronous after Go open = %d; want 1 (NORMAL, the unified pragmas)", sync)
	}

	// Every row, byte-exact (driver-native values vs the golden's raw
	// columns — all TEXT/INTEGER/REAL-declared, the CAST read law's
	// vacuous case; mtime_ns/size/scanned_at are the fixture's own
	// per-run facts and compare exactly).
	rows, err := c.db.SQL().Query("SELECT path, mtime_ns, size, frontmatter_json, banish_tag, " +
		"scanned_at FROM note_reads ORDER BY path")
	if err != nil {
		t.Fatal(err)
	}
	var gotPaths []string
	var gotRows []map[int]any
	for rows.Next() {
		var path, fmJSON, tag string
		var mtime, size int64
		var scanned float64
		if err := rows.Scan(&path, &mtime, &size, &fmJSON, &tag, &scanned); err != nil {
			t.Fatal(err)
		}
		gotPaths = append(gotPaths, path)
		gotRows = append(gotRows, map[int]any{0: path, 1: mtime, 2: size,
			3: fmJSON, 4: tag, 5: scanned})
	}
	rows.Close()
	if len(gotRows) != len(fg.Rows) {
		t.Fatalf("fixture rows = %d; golden %d", len(gotRows), len(fg.Rows))
	}
	for i, grow := range fg.Rows {
		var wantPath string
		if err := json.Unmarshal(grow[0], &wantPath); err != nil {
			t.Fatal(err)
		}
		if gotPaths[i] != wantPath {
			t.Errorf("row %d path = %q; golden %q", i, gotPaths[i], wantPath)
		}
		var wantMtime, wantSize int64
		var wantFM, wantTag string
		var wantScanned float64
		if err := json.Unmarshal(grow[1], &wantMtime); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(grow[2], &wantSize); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(grow[3], &wantFM); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(grow[4], &wantTag); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(grow[5], &wantScanned); err != nil {
			t.Fatal(err)
		}
		g := gotRows[i]
		if g[1].(int64) != wantMtime || g[2].(int64) != wantSize {
			t.Errorf("row %d fingerprint = (%d,%d); golden (%d,%d)",
				i, g[1].(int64), g[2].(int64), wantMtime, wantSize)
		}
		if g[3].(string) != wantFM {
			t.Errorf("row %d frontmatter_json diverges:\n got: %s\nwant: %s",
				i, g[3].(string), wantFM)
		}
		if g[4].(string) != wantTag {
			t.Errorf("row %d banish_tag = %q; golden %q", i, g[4].(string), wantTag)
		}
		if g[5].(float64) != wantScanned {
			t.Errorf("row %d scanned_at = %v; golden %v", i, g[5].(float64), wantScanned)
		}
	}

	// scanned_at is a REAL column carrying a float — the reference's
	// time.time() shape, and the Go write's shape.
	var typeof string
	if err := c.db.SQL().QueryRow(
		"SELECT typeof(scanned_at) FROM note_reads LIMIT 1").Scan(&typeof); err != nil {
		t.Fatal(err)
	}
	if typeof != "real" {
		t.Errorf("typeof(scanned_at) = %q; want 'real' (the time.time() float shape)", typeof)
	}

	// The rows served through the ported accessor (dbRow): every
	// fixture row readable byte-exact.
	for i, grow := range fg.Rows {
		var wantPath string
		if err := json.Unmarshal(grow[0], &wantPath); err != nil {
			t.Fatal(err)
		}
		row, ok := c.dbRow(wantPath)
		if !ok {
			t.Errorf("dbRow(%q) miss; golden row %d", wantPath, i)
			continue
		}
		var wantMtime, wantSize int64
		var wantFM, wantTag string
		_ = json.Unmarshal(grow[1], &wantMtime)
		_ = json.Unmarshal(grow[2], &wantSize)
		_ = json.Unmarshal(grow[3], &wantFM)
		_ = json.Unmarshal(grow[4], &wantTag)
		if row.fp.MtimeNS != wantMtime || row.fp.Size != wantSize ||
			row.fmJSON != wantFM || row.tag != wantTag {
			t.Errorf("dbRow(%q) = %+v; golden (%d,%d,%q,%q)", wantPath, row,
				wantMtime, wantSize, wantFM, wantTag)
		}
	}

	// The fixture's paths are scratch-per-run (dead here): every ask
	// through the public doors degrades to the empty shapes, never
	// raising — and the first row's ask leaves the table untouched.
	before := fixtureCount(t, work)
	var deadPath string
	_ = json.Unmarshal(fg.Rows[0][0], &deadPath)
	if got := c.Frontmatter(deadPath).Source; got != "" {
		t.Errorf("frontmatter(dead fixture path).source = %q; want ''", got)
	}
	if c.BanishFrontmatter(deadPath) != nil {
		t.Error("banish_frontmatter(dead fixture path) != nil")
	}
	if got := c.BanishTag(deadPath); got != "" {
		t.Errorf("banish_tag(dead fixture path) = %q; want ''", got)
	}
	if got := c.Text(deadPath, DefaultTextBytes); got != "" {
		t.Errorf("text(dead fixture path) = %q; want ''", got)
	}
	if after := fixtureCount(t, work); after != before {
		t.Errorf("dead-path asks changed the table: %d → %d (a miss must not write)",
			before, after)
	}
}

// ---------------------------------------------------------------------------
// Helpers.
// ---------------------------------------------------------------------------

func fixtureCount(t *testing.T, db string) int {
	t.Helper()
	sq, err := sql.Open("sqlite", db)
	if err != nil {
		t.Fatal(err)
	}
	defer sq.Close()
	var n int
	if err := sq.QueryRow("SELECT COUNT(*) FROM note_reads").Scan(&n); err != nil {
		t.Fatal(err)
	}
	return n
}

func mutateRow(t *testing.T, db, path string, mutate func(map[string]any)) {
	t.Helper()
	sq, err := sql.Open("sqlite", db)
	if err != nil {
		t.Fatal(err)
	}
	defer sq.Close()
	var raw string
	if err := sq.QueryRow("SELECT frontmatter_json FROM note_reads WHERE path = ?",
		path).Scan(&raw); err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(raw), &m); err != nil {
		t.Fatal(err)
	}
	mutate(m)
	out, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := sq.Exec("UPDATE note_reads SET frontmatter_json = ? WHERE path = ?",
		string(out), path); err != nil {
		t.Fatal(err)
	}
}

func readRowVersion(t *testing.T, db, path string) int {
	t.Helper()
	sq, err := sql.Open("sqlite", db)
	if err != nil {
		t.Fatal(err)
	}
	defer sq.Close()
	var raw string
	if err := sq.QueryRow("SELECT frontmatter_json FROM note_reads WHERE path = ?",
		path).Scan(&raw); err != nil {
		t.Fatal(err)
	}
	var row struct {
		V int `json:"v"`
	}
	if err := json.Unmarshal([]byte(raw), &row); err != nil {
		t.Fatalf("row JSON %q: %v", raw, err)
	}
	return row.V
}

func sameStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func sameKVMap(kvs []KV, m map[string]string) bool {
	if len(kvs) != len(m) {
		return false
	}
	for _, kv := range kvs {
		if m[kv.Key] != kv.Value {
			return false
		}
	}
	return true
}

func compareUnified(t *testing.T, name string, got Unified, want unifiedG, ignoreStars bool) error {
	if got.HasFM != want.HasFM {
		return fmt.Errorf("%s: has_fm = %v; reference %v", name, got.HasFM, want.HasFM)
	}
	if got.Source != want.Source || got.Category != want.Category ||
		got.Subcategory != want.Subcategory || got.ManagedBy != want.ManagedBy ||
		got.Kind != want.Kind || got.FetchStatus != want.FetchStatus {
		return fmt.Errorf("%s: string keys = %+v; reference %+v", name, got, want)
	}
	if !sameStrings(got.Tags, want.Tags) {
		return fmt.Errorf("%s: tags = %v; reference %v", name, got.Tags, want.Tags)
	}
	if !sameKVMap(got.Banish, want.Banish) {
		return fmt.Errorf("%s: banish = %v; reference %v", name, got.Banish, want.Banish)
	}
	if got.Locked != want.Locked || got.CategoryLocked != want.CategoryLocked ||
		got.Curated != want.Curated {
		return fmt.Errorf("%s: booleans = (%v,%v,%v); reference (%v,%v,%v)", name,
			got.Locked, got.CategoryLocked, got.Curated,
			want.Locked, want.CategoryLocked, want.Curated)
	}
	if got.PrimaryLanguage != want.PrimaryLanguage || got.Org != want.Org ||
		(!ignoreStars && got.Stars != want.Stars) {
		return fmt.Errorf("%s: repos keys = (%q,%q,%q); reference (%q,%q,%q)", name,
			got.PrimaryLanguage, got.Org, got.Stars,
			want.PrimaryLanguage, want.Org, want.Stars)
	}
	return nil
}

func compareInventory(t *testing.T, name string, got Inventory, want unifiedG) error {
	if got.Source != want.Source || got.Category != want.Category ||
		got.Subcategory != want.Subcategory || got.ManagedBy != want.ManagedBy ||
		got.Kind != want.Kind || got.FetchStatus != want.FetchStatus {
		return fmt.Errorf("%s: string keys = %+v; reference %+v", name, got, want)
	}
	if !sameStrings(got.Tags, want.Tags) {
		return fmt.Errorf("%s: tags = %v; reference %v", name, got.Tags, want.Tags)
	}
	if got.Locked != want.Locked || got.CategoryLocked != want.CategoryLocked ||
		got.Curated != want.Curated {
		return fmt.Errorf("%s: booleans = (%v,%v,%v); reference (%v,%v,%v)", name,
			got.Locked, got.CategoryLocked, got.Curated,
			want.Locked, want.CategoryLocked, want.Curated)
	}
	if got.PrimaryLanguage != want.PrimaryLanguage || got.Org != want.Org ||
		got.Stars != want.Stars {
		return fmt.Errorf("%s: repos keys = (%q,%q,%q); reference (%q,%q,%q)", name,
			got.PrimaryLanguage, got.Org, got.Stars,
			want.PrimaryLanguage, want.Org, want.Stars)
	}
	return nil
}
